export type ReticulumDmEventType =
  | 'message'
  | 'edit'
  | 'delete'
  | 'reaction_add'
  | 'reaction_remove';

export type ReticulumDmDeliveryStatus = 'pending' | 'sent' | 'received';

export interface ReticulumDmEvent {
  eventId: string;
  conversationId: string;
  senderAddress: string;
  recipientAddress: string;
  senderPublicKey: string;
  /** Persistent per-installation stream; absent only on legacy events. */
  senderStreamId?: string;
  senderSeq: number;
  timestamp: number;
  eventType: ReticulumDmEventType;
  targetEventId?: string;
  replyToEventId?: string;
  payload: string;
  payloadHash: string;
  signature: string;
  /** Compatibility signature over the legacy fields, served only to old peers. */
  legacySignature?: string;
  localDeliveryStatus?: ReticulumDmDeliveryStatus;
  localDeliveryUpdatedAt?: number;
  /**
   * Local projection: true when this device authored the event (own_event),
   * false for a stored copy (also of the account's own messages written on
   * another device). Only authored events carry a real delivery status.
   * Never on the wire.
   */
  localOwnEvent?: boolean;
  /**
   * Local projection (GO): when a verified own device of the account (a home
   * Hub) first pulled this own pending event. Never on the wire.
   */
  localOwnDeviceCopiedAt?: number;
  /**
   * Local projection (GO, trackOwnPostDelivery): a Saved Messages post
   * written on this device (since: when) and when another own device fetched
   * it from here. localPostMemberAt is never set on a Saved Messages post.
   * Never on the wire.
   */
  localPostDeliverySince?: number;
  localPostOwnDeviceAt?: number;
  localPostMemberAt?: number;
  /** Local projection hint: this event is at or below a synchronized read watermark. */
  readByOwner?: true;
  /** Local database projection; derived from the signed payload, never trusted from wire input. */
  expiresAt?: number | null;
}

