export interface ReticulumChatManagerOptions {
  dbPath?: string;
  bridge?: ReticulumBridge | null;
  now?: () => number;
  localNotifyDebounceMs?: number;
  /**
   * Fallback rescan of the local-notification directory. The directory watch
   * delivers new files promptly; this only catches missed watch events.
   * Defaults to 2 s; a battery-powered host can pass a much longer interval.
   */
  localNotifyScanIntervalMs?: number;
  signLocalFields?: (
    fields: Record<string, unknown>
  ) => Promise<ReticulumChatLocalSignature | null>;
  validateGroupMember?: (
    groupId: number,
    address: string
  ) => Promise<boolean | null>;
  /** Resolves `null` when Core could not answer (treated as unknown). */
  validateGroupAdmin?: (
    groupId: number,
    address: string
  ) => Promise<boolean | null>;
  getVerifiedReticulumPeers?: () => ReticulumChatVerifiedTransportPeer[];
  getAccountEndpointLeases?: () => ReticulumChatAccountEndpointLease[];
  hasGoodOverlayHealth?: () => boolean;
  resourceStore?: ReticulumResourceStore | null;
  /**
   * Relay other peers' group control wires (state digests, event notices,
   * relay digests) along recorded interest routes. Always-on desktop nodes
   * should keep this on; a battery-powered leaf that comes and goes should
   * not act as a gossip hop. Defaults to true.
   */
  relayGroupControl?: boolean;
  /**
   * Once per signed-in address (guarded in the database), turn this
   * device's recent own DMs that older builds marked 'sent' when the bridge
   * accepted the authorize (before any byte arrived) back into 'pending', so
   * the outbox re-announces them and the next page proves them. GO only;
   * defaults to off.
   */
  repairPrematureDmSentOnce?: boolean;
  /**
   * Record which own posts written on this device another node fetched from
   * here: group messages and attachments (thread replies included) and
   * Saved Messages. The proof is the bridge's terminal 'sent' (RNS proved
   * receipt) for a serve this device authorized; a requester signed with our
   * own address is an own device (a home Hub), any other one a member's
   * node. Nothing new goes on the wire. Tracked posts carry
   * localPostDeliverySince / localPostOwnDeviceAt / localPostMemberAt to the
   * renderer, and proofs are emitted as 'ownPostDelivery'. GO only; defaults
   * to off.
   */
  trackOwnPostDelivery?: boolean;
  /**
   * Answer the local signer's own group membership from the list the host
   * pushed (Core's group list for this account) instead of waiting on the
   * membership validator; Core is still asked in the background and a Core
   * "not a member" wins. At boot an own-address check waits briefly for that
   * list. Peers still check our events against their own Core. GO only;
   * defaults to off.
   */
  ownMembershipLocalFirst?: boolean;
  /**
   * Phone (GO) behaviour switches. Every flag defaults to off, so desktop
   * keeps upstream behaviour; only the mobile engine host sets them.
   */
  mobileProfile?: ReticulumChatMobileProfile;
}

/**
 * Behaviour switches for the GO phone engine. A phone runs one manager on a
 * private database, a slow single worker thread and a small file-handle pool,
 * so some desktop habits cost far more there. Nothing here changes the wire.
 */
export interface ReticulumChatMobileProfile {
  /** Wake-up notes for stored events stay in memory instead of one file each. */
  localNotifyInMemory?: boolean;
  /** Local storage failures (staging, EMFILE/ENOENT) are not charged to peers. */
  localFailuresAreLocal?: boolean;
  /** Skipped channel metadata is projected again when admin status changes. */
  reprojectSkippedChannelMetadata?: boolean;
  /** Metadata snapshot requests stop looping and recover from failures. */
  metadataSnapshotRecovery?: boolean;
  /** Snapshots signed by a former admin are ignored, not a peer violation. */
  lenientStaleSnapshotSigner?: boolean;
  /** Admins apply the public snapshot while no full snapshot is stored. */
  adminPublicSnapshotFallback?: boolean;
  /** Membership-deferred events keep their pull and refund gap attempts. */
  keepMembershipDeferredPulls?: boolean;
  /** Authors of an incoming page are checked in one batch up front. */
  prefetchPageAuthorMemberships?: boolean;
  /** Peers that answered history_unavailable are skipped for a while. */
  authorGapNoHistoryExclusion?: boolean;
  /** Recent gap rows are tried before old ones. */
  recentGapsFirst?: boolean;
  /** Gap rows back off on a streak of denials, persisted across restarts. */
  gapDenialBackoff?: boolean;
  /** Provider auths are handled at once instead of queueing behind status items. */
  immediateProviderAuth?: boolean;
  /** A busy history serve answers with a reason Hubs rotate on. */
  rotatableServeBusy?: boolean;
  /** Digest state builds run inline without a fake worker fallback warning. */
  inlineDigestBuilds?: boolean;
  /**
   * Copy diagnostics: each author-range denial is sorted by the age of the
   * stored message after the gap (old / recent / undated). Costs one indexed
   * read per denial; without it denials are counted unsorted.
   */
  gapOutcomeAges?: boolean;
  /**
   * Gap rows whose next stored message is older than the serve floor are
   * parked for 30 days and asked of Hub-class peers only, once each: no GO
   * peer serves them and Hubs rarely still hold them.
   */
  authorGapAgeAware?: boolean;
  /**
   * A channel row that came from a snapshot signed by a current admin is the
   * base for later edits by current admins, even when its creator is no
   * longer an admin. Unverified authors are never projected.
   */
  snapshotVouchedChannelRows?: boolean;
  /**
   * While Core cannot answer, a history serve may still go to a requester
   * Core confirmed as a member within this many ms. Never used for accepting
   * events, calendar or admin checks. Unset or 0 = off.
   */
  staleMemberServeTtlMs?: number;
  /**
   * Under load, history-class serves (history pages, author ranges and
   * manifests) are refused at once as busy so the requester rotates. Live
   * events, DM pages and this account's own authors are never shed.
   */
  shedHistoryServesUnderLoad?: boolean;
  /**
   * Signature freshness on serve paths is judged at the moment the request
   * reached this device, not when the busy engine got to it.
   */
  verifyServeAtArrival?: boolean;
  /**
   * A control send that timed out locally but then got a late ok is not
   * sent again, and local timeouts do not count as bridge pressure.
   */
  lateOkCancelsRetry?: boolean;
}

/**
 * Own messages still waiting to leave this installation (manager event
 * 'ownOutboxState', emitted only when a field changes; also
 * getOwnOutboxState()). Mobile hosts use `pending` to keep the engine awake
 * for a short grace window after the app leaves the screen.
 *
 * - pendingCount: own outbound DMs (not Saved Messages) the recipient has not
 *   pulled yet, from the last 7 days (the background flush window).
 * - uncopiedCount: those of them no verified own device has pulled either.
 * - pending: sending work remains that staying awake can finish: a pending DM
 *   inside the 2 h active retry window, an uncopied pending DM while an own
 *   device has an admitted link and its cursor has not passed the DM (so it
 *   would still be re-pushed), a Saved Messages cursor a linked own device
 *   has not confirmed (and may still be re-notified about), or a group notice
 *   owed to an own device. An old DM to a recipient who stays offline counts
 *   in pendingCount but does not keep `pending` true on its own.
 *
 * DMs the one-time premature-'sent' repair (GO) turned back into 'pending'
 * count in none of these until a delivered page settles them: older builds
 * showed them as sent, and most of them were.
 */
export interface ReticulumChatOwnOutboxState {
  pending: boolean;
  pendingCount: number;
  uncopiedCount: number;
}

const RETICULUM_CHAT_MAX_FUTURE_SKEW_MS = 5 * 60_000;
const RETICULUM_CHAT_MAX_AGE_MS = 30 * 24 * 60 * 60 * 1_000;
// History pages and linked event pulls carry events peers already hold. A
// group's digest window is its 200 most recent stored events with no age
// bound, so in a quiet group that window reaches past 30 days; a node that
// refused those events on age could never match the mesh's digest and kept
// re-pulling the same (known) pages from every peer for as long as it ran
// (measured on a fresh phone: ~1 100 known events re-downloaded per 13 min).
// Signature, group and read checks still apply to imported history.
// Since the serve floor below, such older events reach a GO node only from a
// 3.0.x Hub (which serves with no age bound): GO nodes no longer pass them to
// each other. Two GO nodes whose windows differ by events older than the
// floor now match only if a reachable Hub still holds the missing ones;
// otherwise each re-pulls the other's known pages as described above, as GO
// already does with Hubs, whose windows lack GO's older leftovers.
const RETICULUM_CHAT_HISTORY_IMPORT_MAX_AGE_MS = 2 * 365 * 24 * 60 * 60 * 1_000;
// What this node keeps (above) is not what it may hand to peers. Hub 3.0.x
// refuses any event older than RETICULUM_CHAT_MAX_AGE_MS on every import path,
// and on a history page counts each one as a protocol violation against the
// provider (3 abort the page, 3 in a row cool the provider down). So history
// pages, author ranges and single event serves carry only events newer than
// this. The margin covers the requester checking an event later than this
// node built the page (serve queue, transfer, its own import queue, deferred
// membership checks) and a clock difference between the two devices of up to
// most of a day. It costs little: an event in the margin is under a day from
// the requester's own 30 day limit (and from general channel expiry).
// The floor applies to every requester, GO nodes included, although they
// import up to RETICULUM_CHAT_HISTORY_IMPORT_MAX_AGE_MS. So GO hands no GO
// phone or GO-branch desktop anything older than it: channel metadata events,
// messages in channels with no expiry, and their reactions and edits. Those
// come only from a 3.0.x Hub that still holds them (and a scroll-back asks
// only the first 3 interested peers). Lifting the floor for GO requesters
// would take a new GO-only hello token checked with peerFeatureSupport in
// these serves (3.0.3 pairs with unknown tokens, as with 'ds1'), at the cost
// of 5-6 of the 7 bytes of hello headroom left; not done.
const RETICULUM_CHAT_SERVE_AGE_MARGIN_MS = 24 * 60 * 60 * 1_000;
export const RETICULUM_CHAT_SERVE_MAX_AGE_MS =
  RETICULUM_CHAT_MAX_AGE_MS - RETICULUM_CHAT_SERVE_AGE_MARGIN_MS;
const RETICULUM_CHAT_MAX_MENTION_ADDRESS_HASHES = 32;
const RETICULUM_CHAT_CONTROL_MAX_AGE_MS = 2 * 60_000;
const RETICULUM_CHAT_CONTROL_MAX_FUTURE_SKEW_MS = 30_000;
const RETICULUM_CHAT_TYPING_TTL_MS = 8_000;
const RETICULUM_CHAT_TYPING_REFRESH_MS = 3_000;
const RETICULUM_LAND_SOCIAL_ACTION_MIN_INTERVAL_MS = 1_200;
const RETICULUM_LAND_SOCIAL_ACTION_RATE_WINDOW_MS = 10_000;
const RETICULUM_LAND_SOCIAL_ACTION_RATE_MAX = 5;
const RETICULUM_LAND_SOCIAL_ACTION_RATE_KEYS_MAX = 2_048;
const RETICULUM_LAND_ACTION_PENDING_TTL_MS = 5_000;
const RETICULUM_LAND_ACTION_PENDING_MAX = 128;
const RETICULUM_LAND_SESSION_ID_MAX_LENGTH = 16;
