export function buildReticulumLandStateSignedFields(input: {
  groupId: number;
  authorAddress: string;
  sessionId: string;
  sequence: number;
  x: number;
  y: number;
  roomId?: string;
  direction?: string;
  movement?: string;
  afk: boolean;
  dnd: boolean;
  voiceEnabled?: boolean;
  voiceMuted?: boolean;
  skinId: number;
  timestamp: number;
}): Record<string, unknown> {
  const signedFields: Record<string, unknown> = {
    authorAddress: input.authorAddress,
    direction: input.direction ?? '',
    groupId: input.groupId,
    movement: input.movement ?? '',
    afk: input.afk,
    dnd: input.dnd,
    skinId: input.skinId,
    roomId: input.roomId ?? '',
    sequence: input.sequence,
    sessionId: input.sessionId,
    timestamp: input.timestamp,
    type: 'QORTAL_LAND_STATE',
    x: input.x,
    y: input.y,
  };
  if (
    typeof input.voiceEnabled === 'boolean' ||
    typeof input.voiceMuted === 'boolean'
  ) {
    signedFields.voiceEnabled = input.voiceEnabled === true;
    signedFields.voiceMuted = input.voiceMuted === true;
  }
  return signedFields;
}

function encodeReticulumLandAvailability(
  afk: boolean,
  dnd: boolean,
  voiceEnabled: boolean,
  voiceMuted: boolean
): number {
  return (
    (afk ? 1 : 0) |
    (dnd ? 2 : 0) |
    (voiceEnabled ? 4 : 0) |
    (voiceMuted ? 8 : 0)
  );
}

function decodeReticulumLandAvailability(value: unknown): {
  afk: boolean;
  dnd: boolean;
  voiceEnabled: boolean;
  voiceMuted: boolean;
} | null {
  const availability = value == null ? 0 : Number(value);
  if (!Number.isInteger(availability) || availability < 0 || availability > 15)
    return null;
  return {
    afk: (availability & 1) !== 0,
    dnd: (availability & 2) !== 0,
    voiceEnabled: (availability & 4) !== 0,
    voiceMuted: (availability & 8) !== 0,
  };
}

export const RETICULUM_LAND_SOCIAL_ACTIONS = [
  'buzz',
  'love',
  'devil',
  'angel',
  'rain',
  'sunshine',
] as const;

export type ReticulumLandSocialAction =
  (typeof RETICULUM_LAND_SOCIAL_ACTIONS)[number];

function isReticulumLandSocialAction(
  value: string
): value is ReticulumLandSocialAction {
  return (RETICULUM_LAND_SOCIAL_ACTIONS as readonly string[]).includes(value);
}

export function buildReticulumLandActionSignedFields(input: {
  groupId: number;
  actionId: string;
  actionType: string;
  fromAddress: string;
  sourceSessionId: string;
  sequence: number;
  toAddress: string;
  targetSessionId: string;
  amount?: number;
  roomId?: string;
  timestamp: number;
}): Record<string, unknown> {
  return {
    actionId: input.actionId,
    actionType: input.actionType,
    amount: input.amount ?? 0,
    fromAddress: input.fromAddress,
    groupId: input.groupId,
    roomId: input.roomId ?? '',
    sequence: input.sequence,
    sourceSessionId: input.sourceSessionId,
    targetSessionId: input.targetSessionId,
    timestamp: input.timestamp,
    toAddress: input.toAddress,
    type: 'QORTAL_LAND_ACTION',
  };
}

function encodeLandActionType(actionType: string): string {
  switch (actionType) {
    case 'qort_received':
      return 'q';
    case 'buzz':
      return 'b';
    case 'love':
      return 'l';
    case 'devil':
      return 'd';
    case 'angel':
      return 'a';
    case 'rain':
      return 'r';
    case 'sunshine':
      return 's';
    default:
      return '';
  }
}

function decodeLandActionType(actionType: unknown): string {
  const value =
    typeof actionType === 'string' ? actionType.trim().toLowerCase() : '';
  switch (value) {
    case 'q':
      return 'qort_received';
    case 'b':
      return 'buzz';
    case 'l':
      return 'love';
    case 'd':
      return 'devil';
    case 'a':
      return 'angel';
    case 'r':
      return 'rain';
    case 's':
      return 'sunshine';
    default:
      return '';
  }
}

function compactLandSessionIdForWire(sessionId: string): string {
  const normalized = sessionId.trim().toLowerCase();
  if (!/^[0-9a-f]{16}$/.test(normalized)) return sessionId;
  return Buffer.from(normalized, 'hex')
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/g, '');
}

function expandLandSessionIdFromWire(sessionId: unknown): string {
  const value = typeof sessionId === 'string' ? sessionId.trim() : '';
  if (!/^[A-Za-z0-9_-]{11}$/.test(value)) return value;
  try {
    const bytes = Buffer.from(
      `${value.replace(/-/g, '+').replace(/_/g, '/')}${'='.repeat((4 - (value.length % 4)) % 4)}`,
      'base64'
    );
    return bytes.length === 8 ? bytes.toString('hex') : value;
  } catch {
    return value;
  }
}

function compactLandActionIdForWire(actionId: string): string {
  const hex = actionId.replace(/-/g, '').toLowerCase();
  if (!/^[0-9a-f]{32}$/.test(hex)) return actionId;
  return Buffer.from(hex, 'hex')
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/g, '');
}

function expandLandActionIdFromWire(actionId: unknown): string {
  const value = typeof actionId === 'string' ? actionId.trim() : '';
  if (!/^[A-Za-z0-9_-]{22}$/.test(value)) return value;
  try {
    const bytes = Buffer.from(
      `${value.replace(/-/g, '+').replace(/_/g, '/')}${'='.repeat((4 - (value.length % 4)) % 4)}`,
      'base64'
    );
    if (bytes.length !== 16) return value;
    const hex = bytes.toString('hex');
    return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
  } catch {
    return value;
  }
}

function buildLandDirectCallChatId(addressA: string, addressB: string): string {
  const first = String(addressA || '').trim();
  const second = String(addressB || '').trim();
  if (!first || !second) return '';
  return `direct:${[first, second].sort().join(':')}`;
}

export function buildReticulumLandCallV2SignedFields(input: {
  groupId: number;
  callType: string;
  callId: string;
  fromAddress: string;
  fromPublicKey: string;
  toAddress: string;
  sourceSessionId: string;
  targetSessionId: string;
  sourceDestinationHash: string;
  targetDestinationHash: string;
  reason?: string;
  roomId?: string;
  timestamp: number;
}): Record<string, unknown> {
  return {
    authorAddress: input.fromAddress,
    authorPublicKey: input.fromPublicKey,
    callId: input.callId,
    callType: input.callType,
    groupId: input.groupId,
    reason: input.reason ?? '',
    roomId: input.roomId ?? '',
    sourceSessionId: input.sourceSessionId,
    sourceDestinationHash: input.sourceDestinationHash,
    targetDestinationHash: input.targetDestinationHash,
    targetSessionId: input.targetSessionId,
    timestamp: input.timestamp,
    toAddress: input.toAddress,
    type: 'QORTAL_LAND_CALL_V2',
  };
}

export function verifyReticulumLandCallV2Wire(
  wire: Extract<ReticulumChatWire, { k: 'lc2' }>,
  now = Date.now(),
  endpoints?: {
    sourceDestinationHash: string;
    targetDestinationHash: string;
  }
): {
  groupId: number;
  callType: string;
  callId: string;
  fromAddress: string;
  toAddress: string;
  sourceSessionId: string;
  targetSessionId: string;
  sourceDestinationHash: string;
  targetDestinationHash: string;
  fromPublicKey: string;
  signature: string;
  reason: string;
  roomId: string;
  timestamp: number;
} | null {
  try {
    const groupId = Number(wire.g);
    const callType = decodeLandCallType(wire.y);
    const callId = typeof wire.c === 'string' ? wire.c.trim() : '';
    const toAddress = typeof wire.b === 'string' ? wire.b.trim() : '';
    const sourceSessionId = expandLandSessionIdFromWire(wire.f);
    // `r` is reserved by the Reticulum bridge for the authenticated sender
    // destination and is stamped onto every transported wire. Keep the Land
    // target session in its own field so transport cannot overwrite signed
    // call data after the sender has verified it.
    const targetSessionId = expandLandSessionIdFromWire(wire.j);
    const sourceDestinationHash = String(endpoints?.sourceDestinationHash || '')
      .trim()
      .toLowerCase();
    const targetDestinationHash = String(endpoints?.targetDestinationHash || '')
      .trim()
      .toLowerCase();
    const fromPublicKey = typeof wire.p === 'string' ? wire.p.trim() : '';
    const signature = typeof wire.z === 'string' ? wire.z.trim() : '';
    const reason = typeof wire.n === 'string' ? wire.n.trim().slice(0, 32) : '';
    const roomId = typeof wire.u === 'string' ? wire.u.trim().slice(0, 16) : '';
    const timestamp = Number(wire.s);
    const fromAddress = deriveAddressFromPublicKey(fromPublicKey);
    if (
      !Number.isSafeInteger(groupId) ||
      groupId <= 0 ||
      !['request', 'accept', 'reject', 'hangup'].includes(callType) ||
      !/^[a-zA-Z0-9_-]{8,64}$/.test(callId) ||
      !fromAddress ||
      !toAddress ||
      !sourceSessionId ||
      sourceSessionId.length > RETICULUM_LAND_SESSION_ID_MAX_LENGTH ||
      !targetSessionId ||
      targetSessionId.length > RETICULUM_LAND_SESSION_ID_MAX_LENGTH ||
      !/^[0-9a-f]{32}$/.test(sourceDestinationHash) ||
      !/^[0-9a-f]{32}$/.test(targetDestinationHash) ||
      !signature ||
      !Number.isSafeInteger(timestamp) ||
      timestamp > now + RETICULUM_CHAT_CONTROL_MAX_FUTURE_SKEW_MS ||
      timestamp < now - RETICULUM_CHAT_CONTROL_MAX_AGE_MS
    ) {
      return null;
    }
    const valid = verifyEd25519Detached(
      new Uint8Array(
        canonicalizeForSigning(
          buildReticulumLandCallV2SignedFields({
            groupId,
            callType,
            callId,
            fromAddress,
            fromPublicKey,
            toAddress,
            sourceSessionId,
            targetSessionId,
            sourceDestinationHash,
            targetDestinationHash,
            reason,
            roomId,
            timestamp,
          })
        )
      ),
      new Uint8Array(base58Decode(signature)),
      new Uint8Array(base58Decode(fromPublicKey))
    );
    return valid
      ? {
          groupId,
          callType,
          callId,
          fromAddress,
          toAddress,
          sourceSessionId,
          targetSessionId,
          sourceDestinationHash,
          targetDestinationHash,
          fromPublicKey,
          signature,
          reason,
          roomId,
          timestamp,
        }
      : null;
  } catch {
    return null;
  }
}

function encodeLandCallType(callType: string): string {
  switch (callType) {
    case 'request':
      return 'q';
    case 'accept':
      return 'a';
    case 'reject':
      return 'j';
    case 'hangup':
      return 'h';
    case 'status':
      return 's';
    case 'ended':
      return 'e';
    case 'game_status':
      return 'g';
    case 'game_ended':
      return 'x';
    default:
      return '';
  }
}

function decodeLandCallType(callType: unknown): string {
  const value =
    typeof callType === 'string' ? callType.trim().toLowerCase() : '';
  switch (value) {
    case 'q':
      return 'request';
    case 'a':
      return 'accept';
    case 'j':
      return 'reject';
    case 'h':
      return 'hangup';
    case 's':
      return 'status';
    case 'e':
      return 'ended';
    case 'g':
      return 'game_status';
    case 'x':
      return 'game_ended';
    default:
      return value;
  }
}

